if (response && response.webhook_id) return [];
// The event names what was deleted, so ask for the rest, and keep the event when the store no longer has it.
try {
  return [call({ method: 'GET', url: '/wp-json/wc/v3/products/' + response.id, query: { per_page: '10' } })];
} catch (e) {
  return [response];
}

